              {qpResult&&qpResult.error&&<div style={{marginTop:8,fontSize:11,color:"#B83232"}}>Erreur: {qpResult.error}</div>}
              {qpResult&&!qpResult.loading&&!qpResult.error&&qpResult.concordance===true&&(
